INSERT INTO fcc_callback_task(
  id, source_call_id, customer_number, did_number, missed_at, missed_reason, status
)
SELECT #{id}, #{callId}, #{number}, #{did}, UTC_TIMESTAMP(3), #{reason}, 'PENDING'
WHERE NOT EXISTS (
  SELECT 1 FROM fcc_callback_task WHERE source_call_id = #{callId}
)
